{"code":"{% extends "base.html" %}

{% block title %}{{ chat_data.chat_name }} | LLMChat App{% endblock %}

{% block content %}
<div class="chat-header mb-3">
  <h2 class="mb-1">{{ chat_data.chat_name }}</h2>
  <div class="text-muted small">Started: {{ chat_data.time }}</div>
</div>
<div class="chat-window p-3 rounded" style="background: var(--bs-light, #f8f9fa); min-height: 400px;">
  {% for msg in chat_data.history %}
    <div class="chat-message mb-3">
      {% if msg.role == 'user' %}
        <div class="d-flex">
          <div class="chat-bubble user ms-auto bg-primary text-white p-2 rounded" style="max-width: 70%;">
            <span>{{ msg.content }}</span>
          </div>
        </div>
      {% elif msg.role == 'assistant' %}
        <div class="d-flex">
          <div class="chat-bubble assistant me-auto bg-secondary text-white p-2 rounded" style="max-width: 70%;">
            <span>{{ msg.content }}</span>
          </div>
        </div>
      {% elif msg.role == 'system' %}
        <div class="text-center text-muted small mb-2">{{ msg.content }}</div>
      {% endif %}
    </div>
  {% endfor %}
</div>
{% endblock %}
","explanation":"Format the chat view as a chat window: user messages right-aligned, assistant left-aligned, system messages centered and muted. Add basic styling for a chat-like appearance.","filePath":"/home/aritra/Documents/temp/LLMchat/templates/chat_view.html"}

